/**
 * Recurring-issue rules. Every tenant read is filtered by `orgId`; the job's
 * sweep is the one deliberate cross-tenant read.
 */
import { and, asc, count, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toRecurringIssue } from "./_mappers";
import type { IssuePriority } from "@/types/issue";
import type { OrgId, ProjectId, UserId } from "@/types/common";
import type {
  RecurrenceCadence,
  RecurringIssue,
} from "@/types/recurring-issue";

export type NewRecurringIssue = {
  orgId: OrgId;
  projectId: ProjectId;
  title: string;
  priority: IssuePriority;
  assigneeId: UserId | null;
  cadence: RecurrenceCadence;
  weekday: number | null;
  timezone: string;
  startsOn: string;
  createdBy: UserId;
};

/** Insertion order: `rowid` is monotonic even for same-millisecond rows. */
const CREATION_ORDER = [asc(recurringIssues.createdAt), asc(sql`rowid`)];

export async function findRecurringIssueById(
  orgId: OrgId,
  id: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)),
    )
    .get();
  return row ? toRecurringIssue(row) : null;
}

export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(...CREATION_ORDER)
    .all()
    .map(toRecurringIssue);
}

/** The `recurringIssues` quota compares against this; paused rules count. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export async function insertRecurringIssue(
  input: NewRecurringIssue,
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      ...input,
      lastOccurrenceOn: null,
      paused: false,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toRecurringIssue(row);
}

export async function updateRecurringIssue(
  orgId: OrgId,
  id: string,
  patch: { paused?: boolean; lastOccurrenceOn?: string | null },
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ ...patch, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Recurring issue ${id} not found`);
  return toRecurringIssue(row);
}

/**
 * Every non-paused rule of every organization, for the background job.
 * Cross-tenant on purpose — the job is not a request.
 */
export async function listActiveRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(...CREATION_ORDER)
    .all()
    .map(toRecurringIssue);
}
EOF
