    .returning()
    .get();

  if (!row) throw new Error(`Recurring issue ${id} not found`);
  return toRecurringIssue(row);
}

/**
 * Every non-paused rule of every organization, for the background job.
 * Cross-tenant on purpose — the job is not a request.
 */
export async function listActiveRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(...CREATION_ORDER)
    .all()
    .map(toRecurringIssue);
}
