/**
 * Files the latest due occurrence of every non-paused recurring-issue rule as
 * an ordinary issue, on behalf of the rule's creator.
 *
 * Must call (do not reimplement): createIssue, can
 */
import { createLogger } from "@/lib/logger";
import { can, PermissionDeniedError } from "@/lib/permissions";
import { createIssueSchema } from "@/schemas/issue";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { projectResource } from "@/server/services/_support";
import { createIssue } from "@/server/services/issue-service";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

/** The calendar day (`YYYY-MM-DD`) `now` falls on in `timeZone`. */
export function localDateIn(now: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const part = (type: string) =>
    parts.find((candidate) => candidate.type === type)?.value ?? "";
  return `${part("year").padStart(4, "0")}-${part("month")}-${part("day")}`;
}

function toUtcDay(date: string): Date {
  const [year, month, day] = date.split("-").map(Number);
  return new Date(Date.UTC(year!, month! - 1, day!));
}

function fromUtcDay(date: Date): string {
  return date.toISOString().slice(0, 10);
}

/** ISO weekday of a `YYYY-MM-DD` date: 1 = Monday … 7 = Sunday. */
function isoWeekday(date: string): number {
  const day = toUtcDay(date).getUTCDay();
  return day === 0 ? 7 : day;
}

/**
 * The latest occurrence of `rule` whose local day has started by `now`, or
 * `null` when none has (the rule starts in the future).
 */
export function latestOccurrence(
  rule: Pick<RecurringIssue, "cadence" | "weekday" | "timezone" | "startsOn">,
  now: Date,
): string | null {
  const today = localDateIn(now, rule.timezone);
  let candidate = today;

  if (rule.cadence === "weekly") {
    if (rule.weekday === null) return null;
    const back = (isoWeekday(today) - rule.weekday + 7) % 7;
    const day = toUtcDay(today);
    day.setUTCDate(day.getUTCDate() - back);
    candidate = fromUtcDay(day);
  }

  return candidate >= rule.startsOn ? candidate : null;
}

/** What happened to one rule in one pass. */
type Outcome = "created" | "skipped" | "paused";

async function processRule(
  rule: RecurringIssue,
  now: Date,
): Promise<Outcome> {
  const occurrence = latestOccurrence(rule, now);
  if (occurrence === null) return "skipped";
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return "skipped";
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (!project || project.archivedAt !== null) return "skipped";

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const actor: Actor | null =
    creator && creator.status === "active"
      ? { userId: rule.createdBy, orgId: rule.orgId, role: creator.role }
      : null;

  if (actor === null || !can(actor, "issue:create", projectResource(project))) {
    await recurringIssueRepo.updateRecurringIssue(rule.orgId, rule.id, {
      paused: true,
    });
    return "paused";
  }

  let assigneeId = rule.assigneeId;
  if (assigneeId !== null) {
    const assignee = await memberRepo.findMember(rule.orgId, assigneeId);
    if (!assignee || assignee.status !== "active") assigneeId = null;
  }

  const input = createIssueSchema.parse({
    orgId: rule.orgId,
    projectId: rule.projectId,
    title: `${rule.title} (${occurrence})`,
    description: null,
    status: "backlog",
    priority: rule.priority,
    assigneeId,
    dueAt: null,
    labelIds: [],
  });

  try {
    await createIssue(actor, input);
  } catch (error) {
    if (error instanceof PermissionDeniedError) {
      await recurringIssueRepo.updateRecurringIssue(rule.orgId, rule.id, {
        paused: true,
      });
      return "paused";
    }
    throw error;
  }

  await recurringIssueRepo.updateRecurringIssue(rule.orgId, rule.id, {
    lastOccurrenceOn: occurrence,
  });
  return "created";
}

/**
 * One pass over every non-paused rule. Missed occurrences are never
 * back-filled — at most one issue per rule, for its latest started
 * occurrence — and one rule's failure never stops the others.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        const outcome = await processRule(rule, now);
        if (outcome === "created") result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.warn("recurring issue not filed", {
          recurringIssueId: rule.id,
          orgId: rule.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
