import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";

const P = "01HZZZPPPPPPPPPPPPPPPPPPPP";
describe("smoke", () => {
  beforeEach(async () => { await setupTestDb(); await resetTestDb(); await seedTwoTenants();
    const db = getDb();
    await db.update(organizations).set({ plan: "starter" }).where(eq(organizations.id, ORG_A));
    await db.insert(members).values({ id: "01HZZZMMMMMMMMMMMMMMMMMMMM", orgId: ORG_A, userId: ALICE, role: "member", status: "active", createdAt: "2026-01-01T00:00:00.000Z", updatedAt: "2026-01-01T00:00:00.000Z" });
    await db.insert(projects).values({ id: P, orgId: ORG_A, name: "W", slug: "w", key: "WEB", createdAt: "2026-01-01T00:00:00.000Z", updatedAt: "2026-01-01T00:00:00.000Z" });
  });
  it("works", async () => {
    const actor = makeActor();
    expect(createRecurringIssueSchema.safeParse({ orgId: ORG_A, projectId: P, title: "abc", cadence: "daily", timezone: "Mars/Base", startsOn: "2026-01-01" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ orgId: ORG_A, projectId: P, title: "abc", cadence: "daily", timezone: "UTC", startsOn: "2026-02-30" }).success).toBe(false);
    const r = await createRecurringIssue(actor, { orgId: ORG_A, projectId: P, title: "Monday planning", cadence: "weekly", weekday: 1, timezone: "Asia/Tokyo", startsOn: "2026-03-01" });
    await createRecurringIssue(actor, { orgId: ORG_A, projectId: P, title: "Daily triage", cadence: "daily", timezone: "America/New_York", startsOn: "2026-03-01" });
    // 2026-03-08 16:00Z = Mon 01:00 Tokyo; NY Sun 11:00 (DST starts 03-08)
    const res = await runRecurringIssueJob(new Date("2026-03-08T16:00:00Z"));
    expect(res.processed).toBe(2);
    expect((await runRecurringIssueJob(new Date("2026-03-08T16:00:00Z"))).processed).toBe(0);
    const titles = getDb().select().from(issues).all().map((i) => i.title).sort();
    expect(titles).toEqual(["Daily triage (2026-03-08)", "Monday planning (2026-03-09)"]);
    const list = await listRecurringIssues(actor, ORG_A);
    expect(list.map((x) => x.lastOccurrenceOn)).toEqual(["2026-03-09", "2026-03-08"]);
    await setRecurringIssuePaused(actor, { orgId: ORG_A, recurringIssueId: r.id, paused: true });
    await createRecurringIssue(actor, { orgId: ORG_A, projectId: P, title: "Third", cadence: "daily", timezone: "UTC", startsOn: "2026-03-01" });
    await expect(createRecurringIssue(actor, { orgId: ORG_A, projectId: P, title: "Fourth", cadence: "daily", timezone: "UTC", startsOn: "2026-03-01" })).rejects.toThrow();
  });
});
